/// 学習時と同じ正規化 + Linear(36→64) → ReLU → Linear(64→32) → ReLU
/// → Linear(32→1) の forward pass。返すのは softmax 前の**スコア**。
/// clamp は分布外入力への安全弁（opp_move_nn と同じ趣旨）
pub fn king_score(features: &[f64; KING_NN_INPUT]) -> f64 {
    let mut x = [0.0f64; KING_NN_INPUT];
    for i in 0..KING_NN_INPUT {
        x[i] = (features[i] - KING_NN_MEAN[i]) / KING_NN_STD[i];
    }
    let mut h1 = [0.0f64; 64];
    for j in 0..64 {
        let mut s = KING_NN_B1[j];
        for i in 0..KING_NN_INPUT {
            s += KING_NN_W1[j][i] * x[i];
        }
        h1[j] = s.max(0.0);
    }
    let mut h2 = [0.0f64; 32];
    for j in 0..32 {
        let mut s = KING_NN_B2[j];
        for i in 0..64 {
            s += KING_NN_W2[j][i] * h1[i];
        }
        h2[j] = s.max(0.0);
    }
    let mut out = KING_NN_B3;
    for i in 0..32 {
        out += KING_NN_W3[i] * h2[i];
    }
    out.clamp(-15.0, 15.0)
}

/// 候補マス集合上の相手玉位置分布（正規化済み）。
/// 学習時と同じマスク（deduce の候補集合 − 自駒マス）を適用する。
/// マスクで空になったら（deduce の健全性違反時のみ起きうる）候補集合そのままの
/// 一様分布に落とす（玉位置の質量を潰す事故を避ける。ansatsu 回帰の教訓）
pub fn king_distribution(ctx: &BeliefContext, cands: &BTreeSet<Coord>) -> Vec<(Coord, f64)> {
    let usable: Vec<Coord> = cands.iter().copied().filter(|&c| !ctx.is_mine(c)).collect();
    if usable.is_empty() {
        let n = cands.len().max(1) as f64;
        return cands.iter().map(|&c| (c, 1.0 / n)).collect();
    }
    let scores: Vec<f64> = usable
        .iter()
        .map(|&c| {
            let base = ctx.features(c);
            let extra = ctx.king_extra(c);
            let mut x = [0.0f64; KING_NN_INPUT];
            x[..BELIEF_FEATURES].copy_from_slice(&base);
            x[BELIEF_FEATURES..].copy_from_slice(&extra);
            king_score(&x)
        })
        .collect();
    let max = scores.iter().copied().fold(f64::MIN, f64::max);
    let exps: Vec<f64> = scores.iter().map(|&s| (s - max).exp()).collect();
    let z: f64 = exps.iter().sum();
    usable
        .into_iter()
        .zip(exps)
        .map(|(c, e)| (c, e / z))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::belief_features::{BELIEF_FEATURE_NAMES, KING_EXTRA_FEATURE_NAMES};
    use crate::board::parse_usi_square;
    use crate::observation::ObservationLog;
    use crate::protocol::Color;

    fn case(pairs: &[(&str, f64)]) -> [f64; KING_NN_INPUT] {
        let names: Vec<&str> = BELIEF_FEATURE_NAMES
            .iter()
            .chain(KING_EXTRA_FEATURE_NAMES.iter())
            .copied()
            .collect();
        let mut f = [0.0f64; KING_NN_INPUT];
        for &(name, v) in pairs {
            let i = names
                .iter()
                .position(|&n| n == name)
                .unwrap_or_else(|| panic!("未知の特徴量名: {name}"));
            f[i] = v;
        }
        f
    }

    /// プレースホルダ（ゼロ重み）のまま誤ってマージする事故のガード
    #[test]
    fn weights_are_not_placeholder_zeros() {
        assert!(
            KING_NN_W1.iter().flatten().any(|&w| w != 0.0),
            "W1が全ゼロ = export_king_belief_weights.py 未実行のプレースホルダ"
        );
        assert!(KING_NN_W2.iter().flatten().any(|&w| w != 0.0));
        assert!(KING_NN_W3.iter().any(|&w| w != 0.0));
    }

    /// numpy側で同じ定数を独立に読み直して計算した値との突き合わせ。
    /// 期待値の再生成は scratchpad の king_crosscheck.py。
    /// **重みを差し替えたら必ず再生成すること**
    #[test]
    fn matches_numpy_cross_check() {
        let init_king_sq = case(&[
            ("prior_occ", 0.25),
            ("opp_board_n", 1.0),
            ("opp_moves_n", 0.05),
            ("file_center", 1.0),
            ("init_opp", 1.0),
            ("init_king", 1.0),
            ("untouched", 1.0),
            ("dist_my_king", 1.0),
            ("dist_opp_last", 1.0),
            ("king_cand", 1.0),
            ("king_cand_frac", 0.5),
        ]);
        let far_square = case(&[
            ("prior_occ", 0.24),
            ("opp_board_n", 0.9),
            ("opp_taken_n", 0.2),
            ("opp_moves_n", 0.5),
            ("depth_opp", 0.625),
            ("file_center", 0.5),
            ("empty_seen", 1.0),
            ("empty_seen_rec", 0.8),
            ("my_attack", 0.6667),
            ("dist_my_king", 0.375),
            ("dist_opp_last", 0.5),
            ("king_cand", 1.0),
            ("king_cand_frac", 0.03),
            ("dist_init_king", 0.75),
        ]);
        let cases: [([f64; KING_NN_INPUT], f64); 3] = [
            // 全ゼロは分布外なので clamp の下限に張り付く（安全弁の確認込み）
            ([0.0; KING_NN_INPUT], -15.0),
            (init_king_sq, 2.2374215709051732),
            (far_square, -6.777457166109448),
        ];
        for (features, expected) in cases {
            let got = king_score(&features);
            assert!(
                (got - expected).abs() < 1e-9,
                "got={got} expected={expected}"
            );
        }
    }

    /// 初期局面: 候補が {5a, 5e} なら初期玉マス 5a が支配的で、分布は正規化されている
    #[test]
    fn initial_position_distribution_is_sane() {
        let ctx = BeliefContext::from_log(Color::Sente, &ObservationLog::default());
        let cands: BTreeSet<Coord> = ["5a", "5e"]
            .iter()
            .map(|s| parse_usi_square(s).unwrap())
            .collect();
        let dist = king_distribution(&ctx, &cands);
        let total: f64 = dist.iter().map(|(_, p)| p).sum();
        assert!((total - 1.0).abs() < 1e-9, "正規化されていない: {total}");
        let p = |s: &str| {
            dist.iter()
                .find(|(c, _)| *c == parse_usi_square(s).unwrap())
                .map_or(0.0, |(_, p)| *p)
        };
        assert!(p("5a") > 0.9, "初期玉マスが支配的でない: {}", p("5a"));
    }

    /// 自駒マスは候補から除外され、全滅時は候補そのまま一様に落ちる
    #[test]
    fn own_squares_are_masked_with_uniform_fallback() {
        let ctx = BeliefContext::from_log(Color::Sente, &ObservationLog::default());
        // 7g は先手の歩 = 自駒マスのみの候補集合（人工的な健全性違反）
        let cands: BTreeSet<Coord> = [parse_usi_square("7g").unwrap()].into_iter().collect();
        let dist = king_distribution(&ctx, &cands);
        assert_eq!(dist.len(), 1);
        assert!((dist[0].1 - 1.0).abs() < 1e-9);
        // 自駒マス + 空きマスなら自駒マスは分布に入らない
        let cands: BTreeSet<Coord> = ["7g", "5a"]
            .iter()
            .map(|s| parse_usi_square(s).unwrap())
            .collect();
        let dist = king_distribution(&ctx, &cands);
        assert_eq!(dist.len(), 1);
        assert_eq!(dist[0].0, parse_usi_square("5a").unwrap());
    }
}
